package com.bank.backup.service;
import com.bank.backup.model.BackupArtifact;
import java.util.logging.*;

public class BackupManager {
    private static final Logger log = Logger.getLogger(BackupManager.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    // Logical: portable SQL/custom dump — larger, slower, restore replays statements
    public BackupArtifact logicalDump(long rows) {
        BackupArtifact a = new BackupArtifact("LOGICAL", rows * 2, 1);
        log.info(() -> "pg_dump produced " + a.getSizeMb() + "MB portable archive");
        return a;
    }
    // Physical: exact file copy — fast, engine-specific
    public BackupArtifact physicalBaseBackup(long dataMb) {
        BackupArtifact a = new BackupArtifact("PHYSICAL", dataMb, 1);
        log.info(() -> "pg_basebackup copied " + a.getSizeMb() + "MB base (exact files)");
        return a;
    }
    // Incremental: only changed WAL since base — small, chained restore
    public BackupArtifact incrementalBackup(long changedMb, int sinceBase) {
        BackupArtifact a = new BackupArtifact("INCREMENTAL", changedMb, 1 + sinceBase);
        log.info(() -> "WAL increment " + a.getSizeMb() + "MB (restore chain length=" + a.getRestoreSteps() + ")");
        return a;
    }
}
