package com.bank.backup;
import com.bank.backup.service.BackupManager;
import java.util.logging.*;

public class BackupDemo {
    public static void main(String[] args) {
        BackupManager bm = new BackupManager();
        bm.logicalDump(2);              // 2 ledger rows
        bm.physicalBaseBackup(500);     // 500MB data dir
        bm.incrementalBackup(12, 3);    // 12MB WAL, 3 increments since base
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
